<script setup>
import{ref,onMounted,nextTick}from'vue'
import * as echarts from'echarts'
import{getDashboard,getOrders,getRequests,getPayment,refundOrder,getAdminUsers,setAdminUserEnabled,getAdminWorks,setAdminWorkStatus,setAdminWorkFeatured,getAdminReviews,deleteAdminReview,getAdminStats}from'../api'
import{ElMessage,ElMessageBox}from'element-plus'
const active=ref('overview'),d=ref({}),orders=ref([]),requests=ref([]),payment=ref({}),users=ref([]),works=ref([]),reviews=ref([]),stats=ref({})
const categoryChart=ref(),orderChart=ref(),trendChart=ref();let charts=[]
const workStatus=s=>({APPROVED:'已通过',PENDING:'待审核',REJECTED:'已驳回'}[s]||s)
async function load(){[d.value,orders.value,requests.value,users.value,works.value,reviews.value,stats.value]=await Promise.all([getDashboard().then(x=>x.data),getOrders().then(x=>x.data),getRequests().then(x=>x.data),getAdminUsers().then(x=>x.data),getAdminWorks().then(x=>x.data),getAdminReviews().then(x=>x.data),getAdminStats().then(x=>x.data)]);for(const o of orders.value){try{payment.value[o.id]=(await getPayment(o.id)).data}catch{}}await nextTick();renderCharts()}
function renderCharts(){charts.forEach(c=>c.dispose());charts=[];if(!categoryChart.value)return;const c1=echarts.init(categoryChart.value);c1.setOption({tooltip:{trigger:'item'},legend:{bottom:0},series:[{type:'pie',radius:['42%','68%'],data:Object.entries(stats.value.categories||{}).map(([name,value])=>({name,value}))}]});charts.push(c1);const c2=echarts.init(orderChart.value);c2.setOption({tooltip:{trigger:'axis'},xAxis:{type:'category',data:Object.keys(stats.value.orderStatus||{}),axisLabel:{rotate:25}},yAxis:{type:'value',minInterval:1},series:[{type:'bar',data:Object.values(stats.value.orderStatus||{})}]});charts.push(c2);const c3=echarts.init(trendChart.value);c3.setOption({tooltip:{trigger:'axis'},xAxis:{type:'category',data:Object.keys(stats.value.sevenDayOrders||{})},yAxis:{type:'value',minInterval:1},series:[{type:'line',smooth:true,areaStyle:{},data:Object.values(stats.value.sevenDayOrders||{})}]});charts.push(c3)}
async function toggleUser(u){try{await setAdminUserEnabled(u.id,!u.enabled);ElMessage.success(u.enabled?'客户已停用':'客户已恢复');load()}catch(e){ElMessage.error(e.response?.data?.message||'操作失败')}}
async function audit(w,status){await setAdminWorkStatus(w.id,status);ElMessage.success(status==='APPROVED'?'作品已通过审核':'作品已驳回');load()}
async function setFeatured(w,value){await setAdminWorkFeatured(w.id,value);ElMessage.success('精选状态已更新');load()}
async function removeReview(r){try{await ElMessageBox.confirm('确认删除该评价？','评价管理',{type:'warning'});await deleteAdminReview(r.id);ElMessage.success('评价已删除');load()}catch(e){}}
async function refund(o){try{const{value}=await ElMessageBox.prompt('请输入退款处理说明','模拟退款',{confirmButtonText:'确认退款',cancelButtonText:'取消',inputValue:'用户取消个性化定制订单'});await refundOrder(o.id,{reason:value});ElMessage.success('模拟退款完成');await load()}catch(e){}}
function tabChanged(){if(active.value==='overview')nextTick(renderCharts)}onMounted(load)
</script>
<template><section class="page-hero admin-hero"><div class="container"><h1>系统运营管理后台</h1><p>覆盖账号、作品审核、评价、订单、支付与经营数据统计。</p></div></section><section class="section"><div class="container"><div class="dashboard-grid"><div class="metric"><small>注册用户</small><b>{{d.users||0}}</b></div><div class="metric"><small>作品总数</small><b>{{d.works||0}}</b></div><div class="metric"><small>定制订单</small><b>{{d.orders||0}}</b></div><div class="metric"><small>已支付金额</small><b>¥{{d.paidAmount||0}}</b></div><div class="metric"><small>退款金额</small><b>¥{{d.refundAmount||0}}</b></div></div>
<el-tabs v-model="active" class="workspace-tabs" @tab-change="tabChanged">
<el-tab-pane label="数据看板" name="overview"><div class="chart-grid"><div class="panel"><h3>作品品类分布</h3><div ref="categoryChart" class="chart"></div></div><div class="panel"><h3>订单状态分布</h3><div ref="orderChart" class="chart"></div></div><div class="panel chart-wide"><h3>近 7 日新增订单</h3><div ref="trendChart" class="chart chart-short"></div></div></div><div class="admin-grid" style="margin-top:20px"><div class="panel"><h3>最近定制需求</h3><el-table :data="requests.slice(0,6)"><el-table-column prop="title" label="需求"/><el-table-column prop="category" label="品类" width="90"/><el-table-column prop="status" label="状态" width="100"/></el-table></div><div class="panel"><h3>角色构成</h3><div class="role-list"><div v-for="(v,k) in stats.roles" :key="k"><span>{{k==='USER'?'普通客户':k==='CREATOR'?'商户':'管理员'}}</span><b>{{v}}</b></div></div></div></div></el-tab-pane>
<el-tab-pane label="用户管理" name="users"><div class="panel"><div class="section-head"><div><h2 style="font-size:23px">注册用户管理</h2><p>普通客户可自由注册；管理员和商户账号固定维护。</p></div></div><el-table :data="users"><el-table-column prop="username" label="用户名"/><el-table-column prop="displayName" label="昵称"/><el-table-column prop="email" label="邮箱" min-width="190"/><el-table-column label="角色" width="110"><template #default="{row}"><el-tag>{{row.role==='USER'?'普通客户':row.role==='CREATOR'?'商户':'管理员'}}</el-tag></template></el-table-column><el-table-column label="状态" width="100"><template #default="{row}"><el-tag :type="row.enabled?'success':'danger'">{{row.enabled?'正常':'已停用'}}</el-tag></template></el-table-column><el-table-column label="操作" width="120"><template #default="{row}"><el-button v-if="row.role==='USER'" size="small" :type="row.enabled?'danger':'success'" plain @click="toggleUser(row)">{{row.enabled?'停用':'恢复'}}</el-button><span v-else class="subtle">固定账号</span></template></el-table-column></el-table></div></el-tab-pane>
<el-tab-pane label="作品审核" name="works"><div class="panel"><div class="section-head"><div><h2 style="font-size:23px">作品审核与推荐</h2><p>商户新增或修改作品后必须重新审核，通过后才能进入作品集。</p></div></div><el-table :data="works"><el-table-column label="作品" min-width="260"><template #default="{row}"><div class="table-work"><img :src="row.image"/><div><b>{{row.title}}</b><small>{{row.category}} · {{row.creatorName}} · ¥{{row.price}}</small></div></div></template></el-table-column><el-table-column label="状态" width="100"><template #default="{row}"><el-tag :type="row.status==='APPROVED'?'success':row.status==='PENDING'?'warning':'danger'">{{workStatus(row.status)}}</el-tag></template></el-table-column><el-table-column label="精选" width="90"><template #default="{row}"><el-switch v-model="row.featured" @change="value=>setFeatured(row,value)"/></template></el-table-column><el-table-column label="审核操作" width="180"><template #default="{row}"><el-button size="small" type="success" @click="audit(row,'APPROVED')">通过</el-button><el-button size="small" type="danger" plain @click="audit(row,'REJECTED')">驳回</el-button></template></el-table-column></el-table></div></el-tab-pane>
<el-tab-pane label="评价管理" name="reviews"><div class="panel"><div class="section-head"><div><h2 style="font-size:23px">作品评价管理</h2><p>查看客户评分与内容，对违规或不当评价执行删除。</p></div></div><el-table :data="reviews"><el-table-column prop="userName" label="用户" width="110"/><el-table-column prop="workId" label="作品ID" width="90"/><el-table-column label="评分" width="150"><template #default="{row}"><el-rate :model-value="row.rating" disabled/></template></el-table-column><el-table-column prop="content" label="评价内容" min-width="320"/><el-table-column label="操作" width="90"><template #default="{row}"><el-button size="small" type="danger" text @click="removeReview(row)">删除</el-button></template></el-table-column></el-table></div></el-tab-pane>
<el-tab-pane label="订单监管" name="orders"><div class="panel"><div class="section-head"><div><h2 style="font-size:23px">订单与支付监管</h2><p>查看订单状态、支付流水，并处理已提交的取消退款申请。</p></div></div><el-table :data="orders"><el-table-column prop="workTitle" label="订单" min-width="220"/><el-table-column prop="customerName" label="客户" width="100"/><el-table-column prop="creatorName" label="商户" width="110"/><el-table-column prop="status" label="状态" width="110"/><el-table-column label="金额" width="100"><template #default="{row}">¥{{row.amount}}</template></el-table-column><el-table-column label="支付" width="140"><template #default="{row}">{{payment[row.id]?.status||'未支付'}}</template></el-table-column><el-table-column label="操作" width="120"><template #default="{row}"><el-button v-if="row.status==='取消申请中'" size="small" type="danger" @click="refund(row)">模拟退款</el-button><span v-else class="subtle">—</span></template></el-table-column></el-table></div></el-tab-pane>
</el-tabs></div></section></template>